<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{api}from'../api/client';
const loading=ref(true),error=ref(''),summary=ref<any>({Properties:{},Leases:{},Finance:{},Operations:{},Cashflow:[],LeaseStatuses:[],UpcomingExpiries:[],TopOverdueBills:[],RecentAuditActions:[]});
const maxCashflow=computed(()=>Math.max(1,...(summary.value.Cashflow||[]).flatMap((x:any)=>[x.Billed||0,x.Received||0])));
const collectionRate=computed(()=>{const billed=(summary.value.Cashflow||[]).reduce((n:number,x:any)=>n+(x.Billed||0),0),received=(summary.value.Cashflow||[]).reduce((n:number,x:any)=>n+(x.Received||0),0);return billed?Math.min(100,received/billed*100):0});
function money(value:number){return `¥${((value||0)/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`}
function percent(value:number){return `${((value||0)/100).toFixed(1)}%`}
function monthLabel(value:string){const parts=value.split('-');return `${Number(parts[1])}月`}
function actionText(value:string){const map:Record<string,string>={'auth.login.succeeded':'用户登录','property.create':'新增房源','lease.create':'创建租约','bill.generate':'生成账单','payment.post':'登记收款','work_order.create':'新增报修','approval.approved':'审批通过'};return map[value]||value}
async function load(){loading.value=true;error.value='';try{summary.value=(await api.get('/dashboard')).data}catch(e:any){error.value=e.response?.data?.error?.message||'仪表盘数据加载失败'}finally{loading.value=false}}
onMounted(load)
</script>
<template><div class="page dashboard-page"><div class="page-title"><div><h1>运营仪表盘</h1><p>从房态、租约、应收、押金、维修和审批维度掌握整体经营情况</p></div><div class="dashboard-actions"><span class="live-dot">实时统计</span><button class="secondary-button" @click="load">刷新数据</button></div></div><p v-if="error" class="form-error">{{error}}</p><div class="metric-grid"><article class="metric-card property"><div class="metric-icon">房</div><div><span>房源总数</span><strong>{{summary.Properties.Total||0}}</strong><small>可租 {{summary.Properties.Available||0}} · 维修 {{summary.Properties.Maintenance||0}}</small></div><b>{{percent(summary.Properties.OccupancyBasisPoints)}} 入住率</b></article><article class="metric-card lease"><div class="metric-icon">约</div><div><span>生效租约</span><strong>{{summary.Leases.Active||0}}</strong><small>30 天内到期 {{summary.Leases.Expiring30Days||0}} 份</small></div><b>{{summary.Leases.Renewed||0}} 次续租</b></article><article class="metric-card finance"><div class="metric-icon">账</div><div><span>应收余额</span><strong>{{money(summary.Finance.Outstanding)}}</strong><small>逾期 {{money(summary.Finance.OverdueOutstanding)}}</small></div><b>{{summary.Finance.OverdueBills||0}} 笔逾期</b></article><article class="metric-card payment"><div class="metric-icon">收</div><div><span>本月收款</span><strong>{{money(summary.Finance.ReceivedThisMonth)}}</strong><small>上月 {{money(summary.Finance.ReceivedPreviousMonth)}}</small></div><b>押金 {{money(summary.Finance.DepositBalance)}}</b></article></div><div class="dashboard-layout"><section class="card trend-card"><div class="card-heading"><div><h3>近六个月账单与收款</h3><p>账单应收与实际收款对比，金额单位为人民币</p></div><span>综合回款率 {{collectionRate.toFixed(1)}}%</span></div><div class="chart-legend"><i class="billed"></i>账单金额<i class="received"></i>实收金额</div><div class="bar-chart"><div v-for="x in summary.Cashflow" :key="x.Month" class="bar-column"><div class="bars"><div class="bar billed" :style="{height:`${Math.max(3,(x.Billed||0)/maxCashflow*150)}px`}" :title="money(x.Billed)"></div><div class="bar received" :style="{height:`${Math.max(3,(x.Received||0)/maxCashflow*150)}px`}" :title="money(x.Received)"></div></div><span>{{monthLabel(x.Month)}}</span></div></div></section><section class="card operation-card"><div class="card-heading"><div><h3>待办事项</h3><p>需要运营人员优先跟进</p></div></div><RouterLink to="/leases"><span class="task-icon blue">期</span><div><strong>即将到期租约</strong><small>未来 30 天内到期</small></div><b>{{summary.Leases.Expiring30Days||0}}</b></RouterLink><RouterLink to="/bills"><span class="task-icon red">逾</span><div><strong>逾期账单</strong><small>尚未完成核销</small></div><b>{{summary.Finance.OverdueBills||0}}</b></RouterLink><RouterLink to="/work-orders"><span class="task-icon orange">修</span><div><strong>超时维修工单</strong><small>超过三天未关闭</small></div><b>{{summary.Operations.OverdueWorkOrders||0}}</b></RouterLink><RouterLink to="/approvals"><span class="task-icon purple">审</span><div><strong>待审批事项</strong><small>等待复核或批准</small></div><b>{{summary.Operations.PendingApprovals||0}}</b></RouterLink><RouterLink to="/settlements"><span class="task-icon green">退</span><div><strong>待完成结算</strong><small>退租费用尚未确认</small></div><b>{{summary.Operations.PendingSettlements||0}}</b></RouterLink></section></div><div class="dashboard-layout lower"><section class="card"><div class="card-heading"><div><h3>即将到期租约</h3><p>建议提前联系租客确认续租意向</p></div><RouterLink to="/leases">查看全部</RouterLink></div><table v-if="summary.UpcomingExpiries?.length" class="data-table compact"><thead><tr><th>房源</th><th>租客</th><th>到期日期</th><th>剩余时间</th></tr></thead><tbody><tr v-for="x in summary.UpcomingExpiries" :key="x.LeaseID"><td><strong>{{x.PropertyLabel}}</strong></td><td>{{x.TenantName}}</td><td>{{String(x.EndDate).slice(0,10)}}</td><td><span class="status-badge">{{x.DaysRemaining}} 天</span></td></tr></tbody></table><div v-else class="empty-state small"><b>近期没有到期租约</b><span>未来 30 天租约状态稳定</span></div></section><section class="card"><div class="card-heading"><div><h3>重点逾期账单</h3><p>按未收金额从高到低排序</p></div><RouterLink to="/bills">前往催收</RouterLink></div><table v-if="summary.TopOverdueBills?.length" class="data-table compact"><thead><tr><th>房源 / 租客</th><th>逾期</th><th>未收金额</th></tr></thead><tbody><tr v-for="x in summary.TopOverdueBills" :key="x.BillID"><td><strong>{{x.PropertyLabel}}</strong><div>{{x.TenantName}}</div></td><td>{{x.OverdueDays}} 天</td><td class="amount-danger">{{money(x.Outstanding)}}</td></tr></tbody></table><div v-else class="empty-state small"><b>没有逾期账单</b><span>当前应收情况良好</span></div></section></div><div class="dashboard-layout lower"><section class="card quick-card"><div class="card-heading"><div><h3>常用业务入口</h3><p>快速发起高频运营动作</p></div></div><div class="quick-grid"><RouterLink to="/properties"><b>⌂</b><span>房源管理</span><small>录入房间与设施</small></RouterLink><RouterLink to="/tenants"><b>人</b><span>租客档案</span><small>登记入住人员</small></RouterLink><RouterLink to="/leases"><b>约</b><span>创建租约</span><small>校验租期冲突</small></RouterLink><RouterLink to="/bills"><b>账</b><span>账单收款</span><small>生成、核销与减免</small></RouterLink><RouterLink to="/work-orders"><b>修</b><span>维修派单</span><small>跟进维修进度</small></RouterLink><RouterLink to="/reports"><b>表</b><span>经营报表</span><small>查看账龄与对账</small></RouterLink></div></section><section class="card audit-card"><div class="card-heading"><div><h3>最近业务动态</h3><p>关键操作实时审计</p></div><RouterLink to="/audits">审计日志</RouterLink></div><div v-for="x in summary.RecentAuditActions" :key="x.ID" class="audit-row"><span></span><div><strong>{{actionText(x.Action)}}</strong><small>{{x.Resource}} · {{String(x.CreatedAt).replace('T',' ').slice(0,16)}}</small></div></div><div v-if="!summary.RecentAuditActions?.length" class="empty-state small"><b>暂无业务动态</b></div></section></div><div v-if="loading" class="dashboard-loading">正在汇总经营数据...</div></div></template>
<style scoped>.dashboard-page{position:relative}.dashboard-actions{display:flex;align-items:center;gap:12px}.live-dot{font-size:12px;color:#168a71;background:#e9f8f3;padding:8px 12px;border-radius:20px}.live-dot:before{content:'';display:inline-block;width:7px;height:7px;background:#20b486;border-radius:50%;margin-right:7px}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:18px}.metric-card{background:#fff;border:1px solid #e7ebf0;border-radius:16px;padding:18px;display:grid;grid-template-columns:48px 1fr;gap:13px;position:relative;box-shadow:0 8px 24px rgba(34,50,75,.04)}.metric-icon{width:46px;height:46px;border-radius:13px;display:grid;place-items:center;font-weight:800}.metric-card span,.metric-card small{display:block;color:#8b96a7}.metric-card strong{display:block;font-size:24px;margin:5px 0;color:#26354b}.metric-card small{font-size:11px}.metric-card>b{position:absolute;right:16px;top:18px;font-size:11px;font-weight:600}.property .metric-icon{background:#e8f8f3;color:#159276}.property>b{color:#159276}.lease .metric-icon{background:#eaf2ff;color:#3979c5}.lease>b{color:#3979c5}.finance .metric-icon{background:#fff0ed;color:#d75e48}.finance>b{color:#d75e48}.payment .metric-icon{background:#f3edff;color:#7955bd}.payment>b{color:#7955bd}.dashboard-layout{display:grid;grid-template-columns:1.6fr 1fr;gap:18px;margin-bottom:18px}.dashboard-layout.lower{grid-template-columns:1fr 1fr}.card-heading{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:18px}.card-heading h3{margin:0 0 5px}.card-heading p{margin:0;color:#929dad;font-size:12px}.card-heading>a,.card-heading>span{font-size:12px;color:#278875;text-decoration:none}.chart-legend{display:flex;align-items:center;justify-content:flex-end;gap:7px;font-size:11px;color:#8b96a6}.chart-legend i{width:9px;height:9px;border-radius:3px;margin-left:9px}.chart-legend .billed{background:#dfe7f3}.chart-legend .received{background:#25ad8b}.bar-chart{height:190px;display:flex;align-items:flex-end;justify-content:space-around;border-bottom:1px solid #e9edf2;padding:0 8px}.bar-column{height:175px;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:7px;min-width:52px}.bars{height:150px;display:flex;align-items:flex-end;gap:5px}.bar{width:13px;border-radius:5px 5px 0 0;min-height:3px}.bar.billed{background:#dfe7f3}.bar.received{background:linear-gradient(180deg,#36c29d,#168f76)}.bar-column>span{font-size:11px;color:#8793a4}.operation-card>a{display:flex;align-items:center;gap:11px;text-decoration:none;color:#27364d;padding:10px 0;border-bottom:1px solid #edf0f4}.operation-card>a:last-child{border-bottom:0}.operation-card a div{flex:1}.operation-card strong,.operation-card small{display:block}.operation-card small{font-size:11px;color:#929dad;margin-top:4px}.operation-card b{font-size:18px}.task-icon{width:36px;height:36px;border-radius:10px;display:grid;place-items:center}.task-icon.blue{background:#eaf2ff;color:#3979c5}.task-icon.red{background:#fff0ed;color:#d75e48}.task-icon.orange{background:#fff3e8;color:#d57d31}.task-icon.purple{background:#f3edff;color:#7955bd}.task-icon.green{background:#e8f8f3;color:#159276}.compact th,.compact td{padding:11px 9px}.amount-danger{color:#d65d49;font-weight:700}.empty-state.small{padding:26px}.quick-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:11px}.quick-grid a{padding:14px;border:1px solid #e5eaf0;border-radius:12px;text-decoration:none;color:#28364d;display:grid;grid-template-columns:38px 1fr;column-gap:10px}.quick-grid b{grid-row:1/3;width:36px;height:36px;border-radius:10px;background:#eaf7f3;color:#168f76;display:grid;place-items:center}.quick-grid span{font-size:12px;font-weight:700}.quick-grid small{font-size:10px;color:#919cac;margin-top:3px}.audit-row{display:flex;gap:12px;padding:9px 0;border-bottom:1px solid #edf0f4}.audit-row>span{width:8px;height:8px;border-radius:50%;background:#25ad8b;margin-top:5px;box-shadow:0 0 0 4px #e8f8f3}.audit-row strong,.audit-row small{display:block}.audit-row strong{font-size:12px}.audit-row small{font-size:10px;color:#929dad;margin-top:4px}.dashboard-loading{position:absolute;inset:70px 0 auto;background:rgba(255,255,255,.92);padding:28px;text-align:center;border-radius:16px;color:#168f76}@media(max-width:1100px){.metric-grid{grid-template-columns:repeat(2,1fr)}.dashboard-layout,.dashboard-layout.lower{grid-template-columns:1fr}}@media(max-width:700px){.metric-grid{grid-template-columns:1fr}.quick-grid{grid-template-columns:1fr 1fr}}</style>
